            properties = {'name': f'random_{vertex_label}_{random.randint(1, 100)}'}
            db_graph.add_vertex(vertex_label, properties)

        for _ in range(5):
            source_vertex_label = random.choice(['Person', 'Company'])
            target_vertex_label = random.choice(['Place', 'Company'])

            source_id = find_vertex_id(graph_db, source_vertex_label)
            target_id = find_vertex_id(graph_db, target_vertex_label)

            properties_edge = {'relationship': f'random_{source_vertex_label}_{target_vertex_label}'}

            db_graph.add_edge(source_id, target_id, properties_edge)

    else:
