```python
import json

def find_apples(obj, path=""""):
    results = []

    if type(obj) == dict:
        for k in obj.keys():
            results += find_apples(obj[k], path + ""/"" + str(k))

    elif type(obj) == list:
        for i, v in enumerate(obj):
            results += find_apples(v, path + ""/"" + str(i))

    elif obj == ""apple"":
        results.append((obj, path))

    return results

def search_json(s):
    d = json.loads(s)
    return find_apples(d)
```
