import random
import datetime
from typing import List, Dict, Union

def generate_random_data(table: str, columns: Dict[str, Union[int, float, str]], num_rows: int) -> str:
    sql = f""INSERT INTO {table} ("" + "", "".join(columns.keys()) + "") VALUES ""

    for i in range(num_rows):
        values = []

        for col, dtype in columns.items():
            if dtype == int:
                value = random.randint(-2147483648, 2147483647)  # SQLite integer range
            elif dtype == float:
                value = random.random() * random.choice([-1, 1])  # Generate a random positive/negative float
            elif dtype == str:
                value = f""'{''.join(random.choices('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ', k=10))}'""  # Random string of length 10
            elif dtype == datetime:
                value = f""'{datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}'""  # Current date and time as a string

            values.append(str(value))

        sql += ""("" + "", "".join(values) + "") ""

    sql = sql.rstrip() + ""

