```",352,,"['The following is the Python code for your task enhanced with scenarios and added complexity. Note that rate limiting, authentication and error handling are implemented using Flask extensions such as `Flask-Limiter` and `flask_jwt_extended` respectively. Versioning system is implemented manually in a way that each PATCH request creates a new version of the resource and stores it in a list. Soft deletion is also implemented, but restoring deleted resources is not included as it's beyond the scope of this task.

```python
from flask import Flask, request, jsonify
from werkzeug.exceptions import NotFound
import json
from flask_limiter import Limiter
from flask_jwt_extended import JWTManager, jwt_required, create_access_token
import datetime

app = Flask(__name__)
limiter = Limiter(app, default_limits=[""200 per day"", ""50 per hour""])
app.config['JWT_SECRET_KEY'] = 'super-secret'  # Change this in production
jwt = JWTManager(app)

class Resource:
    def __init__(self, id, defaults=None):
        self.id = id
        if defaults is None:
            self.data = {}
            self.versions = [{'version': 1, 'changes': {}, 'date_modified': datetime.datetime.now()}]
        else:
            self.data = defaults['fields']
            self.deleted = defaults.get('deleted', False)

    def __repr__(self):
        return f'<Resource {self.id}: {self.data}>'

    def update(self, updates):
        for key in updates:
            if key not in self.data:
                raise ValueError(f""Field '{key}' does not exist"")
        version_number = len(self.versions) + 1
        changes = {**self.data}  # Copy current data
        changes.update(updates)  # Add updates to copy
        self.versions.append({'version': version_number, 'changes': changes, 'date_modified': datetime.datetime.now()})
        self.data = changes

    def delete(self):
        global resources
        self.deleted = True
        return f""Resource {self.id} deleted.""

resources = {}

@app.route('/api/resources/<int:id>', methods=['PATCH'])
def patch_resource(id):
    try:
        resource = resources[id]
    except KeyError:
        return jsonify({'error': 'Resource not found'}), 404

    updates = request.get_json()
    try:
        resource.update(updates)
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

    return jsonify(resource.__dict__)

@app.route('/api/resources/<int:id>', methods=['DELETE'])
def delete_resource(id):
    try:
        resource = resources[id]
    except KeyError:
        return jsonify({'error': 'Resource not found'}), 404

    return jsonify({'message': resource.delete()})

@app.route('/api/token', methods=['POST'])
def create_token():
    token = create_access_token(identity=""example-user"")
    return jsonify({'token': token}), 201

if __name__ == '__main__':
    app.run(debug=True)
```
Please install `flask-jwt-extended` and `Flask-Limiter` via pip before running this script:

```bash
pip install Flask-JWT-Extended flask-limiter
```
