column1:
By integrating these features into one class named `SecureJson`, developers",327,,"['Here is the code for the SecureJson class:

```python
import os
from cryptography.fernet import Fernet
from concurrent.futures import ThreadPoolExecutor
from json import load as json_load
from typing import Any, Dict, List, Callable
from abc import ABC, abstractmethod

class EncryptionScheme(ABC):
    @abstractmethod
    def encrypt(self, data: bytes) -> bytes:
        pass

    @abstractmethod
    def decrypt(self, token: bytes) -> bytes:
        pass

class AES_256_Factory():
    def __init__(self, key):
        self.key = key

    def create_encryption_scheme(self, mode: str) -> EncryptionScheme:
        if mode == 'CBC':
            return AES_256_CBC(self.key)
        elif mode == 'ECB':
            return AES_256_ECB(self.key)
        else:
            raise ValueError(""Invalid mode"")

class SecureJson:
    def __init__(self, config: Dict[str, Any], factory):
        self._config = config
        self.encryption_scheme = factory.create_encryption_scheme(config[""mode""])

    @staticmethod
    def add_factory_function(id: str, factory) -> None:
        SecureJson.registry[id] = factory

    @classmethod
    def create_from_registry(cls, id: str, config: Dict[str, Any]) -> 'SecureJson':
        return cls(config, SecureJson.registry[id])

    def encrypt_json(self, data: Dict[Any, Any]) -> bytes:
        json_data = json_loads(data)
        return self.encryption_scheme.encrypt(json_data)

    def decrypt_ciphertext(self, ciphertext: bytes) -> bytes:
        try:
            plaintext = self.encryption_scheme.decrypt(ciphertext)
            return json_loads(plaintext)
        except Exception as e:
            print(""Error during decryption:"", str(e))

    def encrypt_file(self, input_path: str, output_path: str) -> None:
        with open(input_path, 'rb') as f:
            data = f.read()
        ciphertext = self.encrypt_json(data)
        with open(output_path, 'wb') as f:
            f.write(ciphertext)

    def decrypt_file(self, input_path: str, output_path: str) -> None:
        with open(input_path, 'rb') as f:
            ciphertext = f.read()
        plaintext = self.decrypt_ciphertext(ciphertext)
        with open(output_path, 'wb') as f:
            f.write(plaintext)

    def encrypt_async(self, data: List[Dict[Any, Any]]) -> List[bytes]:
        with ThreadPoolExecutor() as executor:
            futures = [executor.submit(self.encrypt_json, d) for d in data]
        return [future.result() for future in futures]

    def decrypt_async(self, ciphertexts: List[bytes]) -> List[bytes]:
        with ThreadPoolExecutor() as executor:
            futures = [executor.submit(self.decrypt_ciphertext, c) for c in ciphertexts]
        return [future.result() for future in futures]
```

This is a basic implementation of the class and its methods. The encryption and decryption classes are not implemented as they would be too large and depend on your specific requirements. The AES_256_Factory class and AES_256_CBC, AES_256_ECB classes need to be defined accordingly. The add_factory_function function is static and modifies a class variable registry which holds the factory functions.

You would have to implement the encryption and decryption methods for each mode (AES-CBC, AES-ECB) as well as the encryption and decryption of JSON data itself. Also, you need to decide how to handle the salt values for metadata encryption within ciphertexts and MACs for integrity verification. 

The code provided doesn't contain hardware acceleration or memory optimization techniques which would require additional libraries such as OpenSSL or CNG. It also doesn't contain error handling mechanisms for key length or IV length errors during decryption. These features can be added according to your specific requirements and constraints.
