import json

class JsonHandler:
    _registry = {}

    @classmethod
    def add_factory(cls, factory_id, factory_function):
        if not isinstance(factory_id, str) or not callable(factory_function):
            raise ValueError(""Factory ID must be a string and the function must be callable"")
        cls._registry[factory_id] = factory_function

    @classmethod
    def create_instance(cls, factory_id, data):
        if factory_id not in cls._registry:
            raise ValueError(f""Factory with ID '{factory_id}' does not exist"")
        return cls._registry[factory_id](data)

    @staticmethod
    def to_json(obj):
        return json.dumps(obj)

    @staticmethod
    def from_json(json_str):
        return json.loads(json_str)

class User:
    def __init__(self, name, email):
        self.name = name
        self.email = email

class Company:
    def __init__(self, name, address):
        self.name = name
        self.address = address

def create_user(data):
    return User(**data)

def create_company(data):
    return Company(**data)

JsonHandler.add_factory(""user"", create_user)
JsonHandler.add_factory(""company"", create_company)

json_user = JsonHandler.to_json({""name"": ""John Doe"", ""email"": ""john.doe@example.com""})
print(json_user)   # Output: {""name"": ""John Doe"", ""email"": ""john.doe@example.com""}

user_from_json = JsonHandler.create_instance(""user"", json.loads(json_user))
print(user_from_json.name)   # Output: John Doe
