```python
import json
import hashlib
from collections import defaultdict

class JsonRegistry(object):
    _registry = {}
    _file_hashes = defaultdict()

    @classmethod
    def register_factory(cls, name, factory):
        cls._registry[name] = factory

    @classmethod
    def create(cls, name, *args, **kwargs):
        return cls._registry[name](*args, **kwargs)

    @staticmethod
    def hash_file(filename):
        if filename in JsonRegistry._file_hashes:
            return JsonRegistry._file_hashes[filename]

        with open(filename,'rb') as f:
            bytes = f.read() 
            readable_hash = hashlib.md5(bytes).hexdigest()

column2:
            JsonRegistry._file_hashes[filename] = readable_hash
        return readable_hash

class JsonHandler(object):
    def __init__(self, json_data=None):
        if isinstance(json_data, str):
            self.data = json.loads(json_data)
        else:
            self.data = json_data or {}

    @classmethod
    def from_file(cls, filename):
        with open(filename,'r') as f:
            return cls(f.read())

    def to_json(self):
        return json.dumps(self.data)

JsonRegistry.register_factory('json', JsonHandler)
``` 

