```python
import random
class FactorialAndRandomGenerator:
    def __init__(self):
        self.factorial_cache = {}

    def calculate_factorial(self, num):
        if not isinstance(num, int) or num < 0:
            raise ValueError(""Invalid input for factorial calculation."")
        if num == 0:
            return 1
        if num in self.factorial_cache:
            return self.factorial_cache[num]
        result = num * self.calculate_factorial(num - 1)
        self.factorial_cache[num] = result
        return result

    def generate_float(self, min_bound, max_bound):
        return round(random.uniform(min_bound, max_bound), 2)

    def generate_integer(self, min_bound, max_bound):
        return random.randint(min_bound, max_bound)

