```python
import requests
from typing import List, Dict

class ProductRecommendation:
    def __init__(self, api_key: str, base_url: str):
        self.api_key = api_key
        self.base_url = base_url

    def fetch_product_data(self, user_id: int) -> List[Dict]:
        url = f""{self.base_url}/products""
        headers = {""Authorization"": f""Bearer {self.api_key}""}

        try:
            response = requests.get(url, headers=headers)
            response.raise_for_status()
            products = response.json()
            return [p for p in products if p['category'] == 'electronics']
        except requests.exceptions.RequestException as e:
            print(f""Error fetching product data: {e}"")
            return []

    def generate_recommendation(self, user_history: List[str], max_recs: int) -> List[str]:
        recommended_products = []

        for product_id in user_history:
            url = f""{self.base_url}/recommendations/{product_id}""
            headers = {""Authorization"": f""Bearer {self.api_key}""}

            try:
                response = requests.get(url, headers=headers)
                response.raise_for_status()
                recommendations = response.json()

                if len(recommended_products) < max_recs:
                    recommended_products.extend(recommendations)

                    # Remove duplicates
                    recommended_products = list(set(recommended_products))

                if len(recommended_products) >= max_recs:
                    break

            except requests.exceptions.RequestException as e:
                print(f""Error generating recommendation for product {product_id}: {e}"")

        return recommended_products[:max_recs]

def main():
    api_key = ""your_api_key_here""
    base_url = ""https://api.example.com""

