The complexity is increased by adding conditional logic to filter out certain activities and by introducing a separate method for finding the top-performing user.",338,,"[""Here's the code you asked for:

```python
def calculate_total_weighted_score(records, exclude_negative=False):
    total_weighted_score = 0
    highest_user = None
    highest_score = float('-inf')

    for record in records:
        userID, duration, rating = record

        if exclude_negative and (duration < 0 or rating < 0):
            continue

        weighted_score = duration * rating
        total_weighted_score += weighted_score

        if weighted_score > highest_score:
            highest_user = userID
            highest_score = weighted_score

    return {'total_weighted_score': total_weighted_score, 'user_with_highest_score': highest_user}

def find_highest_scoring_user(records):
    scores_and_users = {calculate_total_weighted_score(records)['total_weighted_score']: user for user, _, _ in records}

    return max(scores_and_users.keys(), default=None)
```
