import os
from typing import Dict, List
import subprocess

def modify_kickstart_config(config_file: str, params: Dict[str, str], password: str) -> None:
    modified_config_file = ""modified_kickstart.cfg""

    try:
        os.system(f""cp {config_file} {config_file}.bak"")

        with open(config_file, 'r') as src_f, open(modified_config_file, 'w') as dst_f:
            for line in src_f:
                for placeholder, value in params.items():
                    line = line.replace(placeholder, value)

                if ""ENCRYPTED_PASSWORD"" in line:
                    dst_f.write(line)
                    dst_f.write(f""{password}\n"")
                else:
                    dst_f.write(line)

        subprocess.run([""sed"", ""-i"", f""s/PLACHOLDER/{params['REPLACEMENT']}/g"", modified_config_file])

        print(""Kickstart configuration modified successfully."")
    except subprocess.CalledProcessError as e:
        print(f""An error occurred while modifying the kickstart config: {e}"")

def get_pokemon_weaknesses(pokemon_types: List[str]) -> Dict[str, List[str]]:
    # Assume there is an existing library function like `get_pokemon_type` which returns 
    # pokemon type details such as weak_against from given Pokemon object.
    POKEMON_WEAKNESS = {
        ""fire"": [""ground""],
        ""water"": [""electric""],
        # ... add more weaknesses here
    }

    result = {}
    for pokemon_type in pokemon_types:
        if pokemon_type not in POKEMON_WEAKNESS:
            print(f""Unknown Pokémon type '{pokemon_type}'. Skipping..."")
            continue

        result[pokemon_type] = POKEMON_WEAKNESS[pokemon_type]

    return result
