```python
import json
from typing import Any, Callable, Dict

class JsonHandler:
    _registry = {}

    @classmethod
    def add_factory(cls, factory_id: str, factory_function: Callable[[Dict[str, Any]], Any]):
        if not isinstance(factory_id, str) or not callable(factory_function):
            raise ValueError(""Factory ID must be a string and the function must be callable"")
        cls._registry[factory_id] = factory_function

    @classmethod
    def create_instance(cls, factory_id: str, data: Dict[str, Any]) -> Any:
        if factory_id not in cls._registry:
            raise ValueError(f""Factory with ID '{factory_id}' does not exist"")
        return cls._registry[factory_id](data)

    @staticmethod
    def to_json(obj: Any, custom_encoder=None) -> str:
        if custom_encoder is None:
            return json.dumps(obj)
        else:
            return json.dumps(obj, cls=custom_encoder)

    @staticmethod
    def from_json(json_str: str) -> Any:
        return json.loads(json_str)

class CustomEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, (User, Company)):
            return obj.to_dict()
        return super().default(obj)

class User:
    def __init__(self, name: str, email: str):
        self.name = name
        self.email = email

    def to_dict(self) -> Dict[str, Any]:
        return {""name"": self.name, ""email"": self.email}

class Company:
    def __init__(self, name: str, address: Dict[str, str]):
        self.name = name
        self.address = address

    def to_dict(self) -> Dict[str, Any]:
        return {""name"": self.name, ""address"": self.address}

def create_user(data: Dict[str, str]):
    user = User(**data)
    user.custom_attribute = ""Some custom attribute""
    return user

def create_company(data: Dict[str, Any]):
    company_address = {
       ""street"": data.pop(""street""),
       ""city"": data.pop(""city""),
       ""state"": data.pop(""state""),
       ""zip_code"": data.pop(""zip_code"")
      }
    company = Company(**data)
    company.address_info = company_address
    return company

JsonHandler.add_factory(""user"", create_user)
JsonHandler.add_factory(""company"", create_company)
```
This code creates a factory pattern for creating `User` and `Company` objects from dictionaries of data, and uses custom JSON encoders to serialize these objects to JSON strings. The type map is implicitly defined by the class definitions themselves, as they provide the `to_dict()` method. If you want to explicitly define this mapping (for example, if `User` or `Company` classes are not under your control), you could add a `type_map` parameter to `CustomEncoder`'s constructor and use it in `default()`.
