```python
def read_floats():
    nums = []
    while True:
        try:
            user_input = input(""Enter a float or 'q' to quit: "")
            if user_input.lower() == 'q':
                break
            else:
                nums.append(float(user_input))
        except ValueError:
            print(""That's not a valid number."")
    return nums

def smallest_num(lst):
    if len(lst) == 0:
        return None

    min_val = lst[0]
    for num in lst:
        if num < min_val:
            min_val = num
    return min_val

numbers = read_floats()
print(""The smallest number is: "", smallest_num(numbers))
