```python
import requests
from requests import exceptions

class HTTPRequest:
    def __init__(self):
        self._headers = {}
        self._params = {}
        self._data = None
        self._response = None

    def set_headers(self, headers):
        if isinstance(headers, dict):
            self._headers = headers

    def set_query_params(self, params):
        if isinstance(params, dict):
            self._params = params

    def set_body(self, data):
        self._data = data

    def get(self, url):
        try:
            self._response = requests.get(url, headers=self._headers, params=self._params)
        except (exceptions.MissingSchema, exceptions.InvalidURL, exceptions.ConnectionError) as e:
            print(""Network issue occurred."")

    def post(self, url):
        try:
            self._response = requests.post(url, headers=self._headers, params=self._params, data=self._data)
        except (exceptions.MissingSchema, exceptions.InvalidURL, exceptions.ConnectionError) as e:
            print(""Network issue occurred."")

    def put(self, url):
        try:
            self._response = requests.put(url, headers=self._headers, params=self._params, data=self._data)
        except (exceptions.MissingSchema, exceptions.InvalidURL, exceptions.ConnectionError) as e:
            print(""Network issue occurred."")

    def delete(self, url):
        try:
            self._response = requests.delete(url, headers=self._headers, params=self._params, data=self._data)
        except (exceptions.MissingSchema, exceptions.InvalidURL, exceptions.ConnectionError) as e:
            print(""Network issue occurred."")

    def get_status_code(self):
        if self._response is not None:
            return self._response.status_code
        else:
            return ""No response received.""
```
