class ImageProcessor:
    def __init__(self, directory_path: str, output_format: str = ""JPEG"", cache_directory: str = ""cache""):
        self.directory_path = directory_path
        self.output_format = output_format.lower()
        self.cache_directory = cache_directory

    def _get_image_extension(self, filename: str) -> str:
        return os.path.splitext(filename)[1].lower()

    def _validate_image_type(self, filename: str) -> bool:
        supported_extensions = ["".jpg"", "".jpeg"", "".png""]
        return self._get_image_extension(filename) in supported_extensions

    def _process_image(self, image_path: str) -> Tuple[Image.Image, bool]:
        try:
            image = Image.open(image_path)
            if image.mode != ""RGB"":
                image = image.convert(""RGB"")
            return image, True
        except Exception as e:
            print(f""Error processing {image_path}: {str(e)}"")
            return None, False

    def _transform_image(self, image: Image.Image) -> None:
        resized_image = image.resize((500, 500), resample=Image.NEAREST)
        grayscale_blurred_image = resized_image.convert(""L"").filter(ImageFilter.BLUR)
        enhanced_brightness_image = ImageEnhance.Brightness(grayscale_blurred_image).enhance(1.2)
        enhanced_brightness_image.save(f""{self.cache_directory}/{hashlib.md5(image.filename.encode()).hexdigest()}.{self.output_format}"", optimize=True, quality=95)

    def process_images_in_directory(self):
        if not os.path.exists(self.cache_directory):
            os.makedirs(self.cache_directory)

        for root_dir, _, files in os.walk(self.directory_path):
            for file in files:
                if self._validate_image_type(file):
                    full_file_path = os.path.join(root_dir, file)
                    transformed_img_processed, success = self._process_image(full_file_path)
                    if success:
                        self._transform_image(transformed_img_processed)
