```python
import random

class FactorialAndRandomGenerator:
    def __init__(self):
        self.factorial_cache = {}

    def calculate_factorial(self, num):
        if not isinstance(num, int) or num < 0:
            raise ValueError(""Invalid input for factorial calculation."")
        if num == 0:
            return 1
        if num in self.factorial_cache:
            return self.factorial_cache[num]
        result = num * self.calculate_factorial(num - 1)
        self.factorial_cache[num] = result
        return result

    def generate_float(self, min_bound, max_bound):
        return round(random.uniform(min_bound, max_bound), 2)

    def generate_integer(self, min_bound, max_bound):
        return random.randint(min_bound, max_bound)

    def __str__(self):
        float_min = int(input(""Enter minimum bound for float generation: ""))
        float_max = int(input(""Enter maximum bound for float generation: ""))
        int_min = int(input(""Enter minimum bound for integer generation: ""))
        int_max = int(input(""Enter maximum bound for integer generation: ""))

        print(f""Generated float value between {float_min} and {float_max}: {self.generate_float(float_min, float_max)}"")

        print(f""Generated integer value between {int_min} and {int_max}: {self.generate_integer(int_min, int_max)}"")
``` 

