```python
import json
import hashlib
from collections import defaultdict
import os.path

class JsonHandler:
    def __init__(self):
        self._registry = {
            ""create_json_object"": self._create_json,
            ""read_json_object"": self._read_json,
            ""update_json_object"": self._update_json,
            ""delete_json_object"": self._delete_json
        }

    def execute(self, command, *args):
        if command in self._registry:
            return self._registry[command](*args)

        raise ValueError(f""Unsupported operation {command}"")

    @staticmethod
    def _create_json(filepath, data):
        with open(filepath, 'w') as f:
            json.dump(data, f)

    @staticmethod
    def _read_json(filepath):
        with open(filepath, 'r') as f:
            return json.load(f)

    @staticmethod
    def _update_json(filepath, data):
        current = self._read_json(filepath)
        current.update(data)
        self._create_json(filepath, current)

    @staticmethod
    def _delete_json(filepath):
        if os.path.exists(filepath):
            os.remove(filepath)

    @staticmethod
    def md5_hash(filepath):
        hash_md5 = hashlib.md5()
        with open(filepath, ""rb"") as f:
            for byte_block in iter(lambda: f.read(4096),b""""):
                hash_md5.update(byte_block)
            return hash_md5.hexdigest()
