The program should be flexible in handling different types of text files, such as source code files, logs, or any plain text documents, based on the specified word counts and output requirements provided through command-line arguments.",121,,"['```python
import argparse
import os

def validate_file(f):
    if not os.path.exists(f):
        print(""Error: File not found."")
        exit(1)

def parse_args():
    parser = argparse.ArgumentParser()

    # Add command-line arguments
    parser.add_argument('input', help='Input file name')
    parser.add_argument('-o', '--output', dest='output', help='Output file name')
    parser.add_argument('-w', '--word', action='append', help='Word to count lines for')

    return parser.parse_args()

def main():
    # Parse command-line arguments
    args = parse_args()

    # Validate input file
    validate_file(args.input)

    with open(args.input, 'r') as f:
        lines = f.readlines()

    result = {}
    for word in args.word:
        count = 0
        for line in lines:
            if word in line:
                count += 1
        result[word] = count

    print('Word counts: ', result)

    # Write to output file if provided
    if args.output is not None:
        with open(args.output, 'w') as f:
            for word, count in result.items():
                f.write(f'{word}: {count}\n')

if __name__ == ""__main__"":
    main()
```
