class EncryptionFactory(ABC):
    @abstractmethod
    def create_encryption_instance(self, config: Dict[str, Any]) -> 'EncryptionInstance':
        pass

class EncryptionInstance:
    def __init__(self, encryption_config: Dict[str, Any]):
        self.config = encryption_config

class SecureJson:
    _factory_registry = {}

    @classmethod
    def add_factory_function(cls, factory_id: str, factory_function: EncryptionFactory):
        cls._factory_registry[factory_id] = factory_function

    @classmethod
    def create_from_config(cls, config_path: str) -> 'SecureJson':
        with open(config_path) as file:
            config = json.load(file)
            selected_factory_id = config.get('encryption_factory')
            if selected_factory_id not in cls._factory_registry:
                raise ValueError(f""Invalid factory ID {selected_factory_id}"")
            encryption_factory = cls._factory_registry[selected_factory_id]
            encryption_instance = encryption_factory.create_encryption_instance(config)
            return SecureJson(encryption_instance)

class AES256CBCFactory(EncryptionFactory):
