Please note that this code requires the `xml`, `os`, `random`, `struct`, `Crypto.Cipher`, and `binascii` modules from Python's standard library as well as external packages such as `pycryptodomex` for AES encryption.

```python
import xml.etree.ElementTree as ET
from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes
import os
import random
import struct
import binascii

class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, RX_UE_INFORMATION_TAG, RNTI):
        self.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG
        self.RNTI = RNTI
        self.CRC_INDICATION_REL8_TAG = {'CRCFLAG': random.randint(0, 1)}

class XMLParser:
    def __init__(self, xml_files):
        self.xml_files = xml_files

    def parse_elements(self, element_names):
        data = []
        for file in self.xml_files:
            try:
                tree = ET.parse(file)
                root = tree.getroot()
                for elem_name in element_names:
                    element = root.find(elem_name)
                    if element is not None:
                        data.append(element.text)
                    else:
                        print(f'Element {elem_name} not found in file {file}')
            except ET.ParseError as e:
                print(f'Failed to parse XML file {file}: {str(e)}')
        return data

class EncryptionManager:
    def __init__(self, key):
        self.key = key

    def encrypt(self, raw):
        cipher = AES.new(self.key, AES.MODE_EAX)
        ciphertext, tag = cipher.encrypt_and_digest(raw)
        return (cipher.nonce, ciphertext, tag)

    def decrypt(self, nonce, ciphertext, tag):
        cipher = AES.new(self.key, AES.MODE_EAX, nonce=nonce)
        plaintext = cipher.decrypt(ciphertext)
        try:
            cipher.verify(tag)
            print(""The message is authentic:"", plaintext)
        except ValueError:
            print(""Key incorrect or message corrupted"")
