```python
import os, json, rsa
from collections import namedtuple

FileInfo = namedtuple('FileInfo', 'path size last_modified type')

def get_file_info(directory):
    file_list = []
    for dirpath, _, filenames in os.walk(directory):
        for f in filenames:
            path = os.path.join(dirpath, f)
            size = os.path.getsize(path)
            last_modified = os.path.getmtime(path)
            _, type = os.path.splitext(f)
            file_list.append(FileInfo(path, size, last_modified, type))
    return file_list

class JSONParser:
    def __init__(self, json_file):
        self.json_file = json_file

    def parse_key(self, key):
        try:
            with open(self.json_file) as f:
                data = json.load(f)
            return data[key]
        except (FileNotFoundError, KeyError, json.JSONDecodeError):
            print(""An error occured during parsing the JSON file."")

class RSAEncryption:
    def __init__(self):
        self.public_key, self.private_key = rsa.newkeys(512)

    def encrypt(self, message):
        return rsa.encrypt(message.encode(), self.public_key)

    def decrypt(self, encrypted_msg):
        return rsa.decrypt(encrypted_msg, self.private_key).decode()
```
This is a simplified version of the code. You would have to modify this code according to your requirement and add more error handling mechanisms as needed. Also note that RSA encryption can be computationally intensive, so it's important to use key lengths that are appropriate for your application.
